"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["4096"],{4261(e){e.exports=JSON.parse('{"tag":{"label":"features","permalink":"/es/tags/features","allTagsPath":"/es/tags","count":10,"items":[{"id":"features/search","title":"B\xfasqueda","description":"Una b\xfasqueda para todo tu registro. La parte del servidor est\xe1 construida; la p\xe1gina todav\xeda no est\xe1 terminada y la aplicaci\xf3n lo dice en vez de mostrar una lista vac\xeda.","permalink":"/es/features/search"},{"id":"features/calendar-and-appointments","title":"Calendario y citas","description":"Un calendario para la semana cotidiana y la m\xe9dica, con una lista en cada cita para no olvidar las preguntas que quer\xedas hacer.","permalink":"/es/features/calendar-and-appointments"},{"id":"features/community-and-chats","title":"Comunidad y chats","description":"Grupos con publicaciones y respuestas, mensajes entre cuentas conectadas, bloqueo y una v\xeda de moderaci\xf3n que nunca revela al autor qui\xe9n lo denunci\xf3.","permalink":"/es/features/community-and-chats"},{"id":"features/blood-donation","title":"Donaci\xf3n de sangre","description":"Un directorio p\xfablico de donantes, solicitudes que les llegan y una entrega de contacto concedida una sola vez a una persona y que puede retirarse.","permalink":"/es/features/blood-donation"},{"id":"features/referrals","title":"El programa de invitaciones","description":"Invita a alguien. Cuando confirma su registro, obtienes puntos, una insignia y, al alcanzar el umbral, un mes de un plan de pago. Cada cifra se configura desde la administraci\xf3n.","permalink":"/es/features/referrals"},{"id":"features/tools","title":"Herramientas y calculadoras","description":"Qu\xe9 calculadoras est\xe1n en LifeWell, cu\xe1les est\xe1n en ZTools y por qu\xe9 el directorio contiene sobre todo enlaces en vez de versiones duplicadas.","permalink":"/es/features/tools"},{"id":"features/shopping-list","title":"La lista de compras","description":"Una lista hecha a partir de tus comidas y recetas, o escrita a mano, que puedes compartir como texto sencillo sin que la persona que compra necesite una cuenta.","permalink":"/es/features/shopping-list"},{"id":"features/maps","title":"Mapas y lugares","description":"Sigue las relaciones entre recuerdos, notas, personas, eventos y nombres de lugares guardados. El historial de ubicaci\xf3n es otra opci\xf3n independiente.","permalink":"/es/features/maps"},{"id":"features/professionals","title":"Profesionales","description":"Un directorio de profesionales que crearon su propia ficha. LifeWell no comprueba sus credenciales; muestra su n\xfamero de registro y un enlace para que puedas consultarlo.","permalink":"/es/features/professionals"},{"id":"features/reminders","title":"Recordatorios","description":"Qu\xe9 puede enviarte LifeWell, cu\xe1ndo y en qu\xe9 dispositivo. Tres controles generales, horas de silencio y por qu\xe9 la aplicaci\xf3n no solicita alarmas exactas en Android.","permalink":"/es/features/reminders"}],"unlisted":false}}')}}]);